select lives_ok($$insert into public.events(id,title,starts_at,ends_at,brand_id,assigned_to,visible_to_brand) values('00000000-0000-4000-8000-000000000206','Shared','2026-10-12T07:00Z','2026-10-12T08:00Z','00000000-0000-4000-8000-000000000204','00000000-0000-4000-8000-000000000201',true)$$,'staff creates event');
insert into public.events(id,title,starts_at,ends_at,brand_id,visible_to_brand) values('00000000-0000-4000-8000-000000000207','Hidden','2026-10-12T07:00Z','2026-10-12T08:00Z','00000000-0000-4000-8000-000000000204',false),('00000000-0000-4000-8000-000000000208','Other brand','2026-10-12T07:00Z','2026-10-12T08:00Z','00000000-0000-4000-8000-000000000205',true);
select lives_ok($$update public.events set starts_at='2026-10-13T07:00Z',ends_at='2026-10-13T08:00Z' where id='00000000-0000-4000-8000-000000000206'$$,'staff moves event');
