select is((select count(*) from public.calendar_assignees()),0::bigint,'directory inaccessible to brand');
select throws_ok($$insert into public.events(title,starts_at,ends_at,brand_id) values('Forged','2026-10-12T07:00Z','2026-10-12T08:00Z','00000000-0000-4000-8000-000000000204')$$,'42501',null,'brand cannot create');
