select is((select count(*) from public.events where brand_id in('00000000-0000-4000-8000-000000000204','00000000-0000-4000-8000-000000000205')),3::bigint,'accounting sees calendar');
with x as(update public.events set title='Forged' where id='00000000-0000-4000-8000-000000000206' returning id) select is((select count(*) from x),0::bigint,'accounting cannot update');
